using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Runtime.Serialization;
using System.Text;
namespace CircuitoStudio {
 [DataContract] public enum CableFactorKind {[EnumMember] Temperature,[EnumMember] Grouping}
 [DataContract] public sealed class CableFactorConditions {
  [DataMember] public string Arrangement {get;set;}
  [DataMember] public double AmbientC {get;set;}
  [DataMember] public int GroupCount {get;set;}
  [DataMember] public int LoadedConductors {get;set;}
  public CableFactorConditions Copy(){return (CableFactorConditions)MemberwiseClone();}
  public void Validate(){if(Arrangement!=null&&(Arrangement.Length>2000||Arrangement.IndexOf('\0')>=0))throw new InvalidDataException("Arranjo inválido.");Project.Range(AmbientC,-100,200,"temperatura ambiente");Project.Range(GroupCount,1,10000,"quantidade de circuitos agrupados");Project.Range(LoadedConductors,2,4,"condutores carregados declarados");}
 }
 [DataContract] public sealed class CableFactorRow {
  [DataMember] public string Id {get;set;}
  [DataMember] public CableFactorKind Kind {get;set;}
  [DataMember] public ConductorMaterial Material {get;set;}
  [DataMember] public CableInsulation Insulation {get;set;}
  [DataMember] public string Installation {get;set;}
  [DataMember] public string Arrangement {get;set;}
  [DataMember] public double AmbientC {get;set;}
  [DataMember] public int GroupCount {get;set;}
  [DataMember] public int LoadedConductors {get;set;}
  [DataMember] public double MinSectionMm2 {get;set;}
  [DataMember] public double MaxSectionMm2 {get;set;}
  [DataMember] public double Factor {get;set;}
  [DataMember] public string AmpacityReference {get;set;}
  [DataMember] public string Source {get;set;}
  [DataMember] public string DataVersion {get;set;}
  public CableFactorRow(){Id=Installation=Arrangement=AmpacityReference=Source=DataVersion="";}
  public CableFactorRow Copy(){return (CableFactorRow)MemberwiseClone();}
  public void Validate(){foreach(string text in new[]{Id,Installation,AmpacityReference,Source,DataVersion})if(String.IsNullOrWhiteSpace(text)||text.Length>2000||text.IndexOf('\0')>=0)throw new InvalidDataException("Fator exige ID, instalação, referência da ampacidade, fonte e versão (até 2000 caracteres).");if(!Enum.IsDefined(typeof(CableFactorKind),Kind)||!Enum.IsDefined(typeof(ConductorMaterial),Material)||!Enum.IsDefined(typeof(CableInsulation),Insulation))throw new InvalidDataException("Tipo/material/isolação do fator inválido.");if(Kind==CableFactorKind.Grouping&&String.IsNullOrWhiteSpace(Arrangement))throw new InvalidDataException("Informe o arranjo de agrupamento da fonte.");if(Arrangement!=null&&(Arrangement.Length>2000||Arrangement.IndexOf('\0')>=0))throw new InvalidDataException("Arranjo inválido.");Project.Range(AmbientC,-100,200,"temperatura do fator");if((Kind==CableFactorKind.Grouping&&AmbientC!=0)||(Kind==CableFactorKind.Temperature&&GroupCount!=0))throw new InvalidDataException("Use AmbientC apenas em Temperature e GroupCount apenas em Grouping; o campo não aplicável deve ser zero.");if(Kind==CableFactorKind.Temperature&&AmbientC>=(Insulation==CableInsulation.PVC?70:90))throw new InvalidDataException("Temperatura fora do modelo térmico PVC 70 °C / XLPE 90 °C.");Project.Range(GroupCount,Kind==CableFactorKind.Grouping?1:0,10000,"agrupamento do fator");Project.Range(LoadedConductors,2,4,"condutores carregados");Project.Range(Factor,.001,10,"fator de correção");Project.Range(MinSectionMm2,0,1e6,"seção mínima do fator");Project.Range(MaxSectionMm2,0,1e6,"seção máxima do fator");if(MaxSectionMm2>0&&MinSectionMm2>MaxSectionMm2)throw new InvalidDataException("Faixa de seção do fator invertida.");}
  public override string ToString(){return Id+" · "+Factor.ToString("G6",CultureInfo.CurrentCulture)+" · "+Source+" / "+DataVersion;}
 }
 [DataContract] public sealed class CableFactorSnapshot {
  [DataMember] public CableFactorConditions Conditions {get;set;}
  [DataMember] public CableFactorRow Temperature {get;set;}
  [DataMember] public CableFactorRow Grouping {get;set;}
  public void Validate(){if(Conditions==null||Temperature==null||Grouping==null)throw new InvalidDataException("Registro de fatores incompleto.");Conditions.Validate();if(String.IsNullOrWhiteSpace(Conditions.Arrangement))throw new InvalidDataException("Informe o arranjo de agrupamento conforme a fonte.");Temperature.Validate();Grouping.Validate();if(Temperature.Kind!=CableFactorKind.Temperature||Grouping.Kind!=CableFactorKind.Grouping)throw new InvalidDataException("Fatores de temperatura/agrupamento trocados.");}
 }
 public partial class CableData {
  [DataMember,Browsable(false)] public CableFactorSnapshot FactorsSnapshot {get;set;}
 }
 public static class CableFactors {
  public const string Header="Id;Kind;Material;Insulation;Installation;Arrangement;AmbientC;GroupCount;LoadedConductors;MinSectionMm2;MaxSectionMm2;Factor;AmpacityReference;Source;DataVersion";
  static bool Same(string a,string b){return String.Equals((a??"").Trim(),(b??"").Trim(),StringComparison.OrdinalIgnoreCase);}
  public static bool Matches(CableFactorRow row,CableFactorConditions conditions,ConductorMaterial material,CableInsulation insulation,string installation,string reference,double section){row.Validate();conditions.Validate();return row.Material==material&&row.Insulation==insulation&&Same(row.Installation,installation)&&Same(row.AmpacityReference,reference)&&row.LoadedConductors==conditions.LoadedConductors&&(String.IsNullOrWhiteSpace(row.Arrangement)?row.Kind==CableFactorKind.Temperature:Same(row.Arrangement,conditions.Arrangement))&&(row.Kind==CableFactorKind.Temperature?Math.Abs(row.AmbientC-conditions.AmbientC)<1e-9:row.GroupCount==conditions.GroupCount)&&(row.MinSectionMm2==0||section>=row.MinSectionMm2)&&(row.MaxSectionMm2==0||section<=row.MaxSectionMm2);}
  public static List<CableFactorRow> Filter(IEnumerable<CableFactorRow> rows,Circuit circuit,CableFactorConditions conditions,CableFactorKind kind){if(rows==null||circuit==null||conditions==null)throw new InvalidDataException("Condições/circuito/tabela ausentes.");conditions.Validate();if(conditions.LoadedConductors<(circuit.Phases==PhaseMode.Trifasico?3:2))return new List<CableFactorRow>();return rows.Where(row=>row.Kind==kind&&Matches(row,conditions,circuit.Cable.Material,circuit.Cable.Insulation,circuit.Cable.InstallationMethod,circuit.Cable.Reference,circuit.CableMm2)).ToList();}
  public static void Validate(CableData cable){if(cable.FactorsSnapshot==null)return;var snap=cable.FactorsSnapshot;snap.Validate();if(cable.TemperatureFactor!=snap.Temperature.Factor||cable.GroupingFactor!=snap.Grouping.Factor)throw new InvalidDataException("Altere fatores referenciados pelo painel Condições dos cabos ou remova o vínculo; a referência não pode contradizer os valores.");}
  static bool Applicable(Circuit circuit,ConductorMaterial material,CableInsulation insulation,string installation,string reference,double section,out string detail){var snap=circuit.Cable.FactorsSnapshot;if(snap==null){detail="Fatores numéricos declarados manualmente; fonte/versão das correções não registrada.";return true;}snap.Validate();bool count=snap.Conditions.LoadedConductors>=(circuit.Phases==PhaseMode.Trifasico?3:2);bool applies=count&&Matches(snap.Temperature,snap.Conditions,material,insulation,installation,reference,section)&&Matches(snap.Grouping,snap.Conditions,material,insulation,installation,reference,section);detail=applies?"Condições compatíveis; fonte e versão registradas.":"Fatores referenciados não correspondem ao material, isolação, instalação, seção, ampacidade-base ou condutores carregados; reaplique para a nova condição.";return applies;}
  public static bool Applicable(Circuit circuit,out string detail){return Applicable(circuit,circuit.Cable.Material,circuit.Cable.Insulation,circuit.Cable.InstallationMethod,circuit.Cable.Reference,circuit.CableMm2,out detail);}
  public static bool Applicable(Circuit circuit,CableOption option,out string detail){return Applicable(circuit,option.Copper?ConductorMaterial.Copper:ConductorMaterial.Aluminium,option.Insulation=="PVC"?CableInsulation.PVC:CableInsulation.XLPE,option.Installation,option.Reference,option.SectionMm2,out detail);}
  public static void Apply(Circuit circuit,CableFactorConditions conditions,CableFactorRow temperature,CableFactorRow grouping){if(circuit==null||circuit.Cable==null||conditions==null||temperature==null||grouping==null)throw new InvalidDataException("Informe circuito, condições e os dois fatores.");var snap=new CableFactorSnapshot{Conditions=conditions.Copy(),Temperature=temperature.Copy(),Grouping=grouping.Copy()};snap.Validate();if(snap.Conditions.LoadedConductors<(circuit.Phases==PhaseMode.Trifasico?3:2)||!Matches(snap.Temperature,snap.Conditions,circuit.Cable.Material,circuit.Cable.Insulation,circuit.Cable.InstallationMethod,circuit.Cable.Reference,circuit.CableMm2)||!Matches(snap.Grouping,snap.Conditions,circuit.Cable.Material,circuit.Cable.Insulation,circuit.Cable.InstallationMethod,circuit.Cable.Reference,circuit.CableMm2))throw new InvalidDataException("Nenhuma aplicação: confira tipo, condições e referência da tabela-base.");circuit.Cable.TemperatureFactor=snap.Temperature.Factor;circuit.Cable.GroupingFactor=snap.Grouping.Factor;circuit.Cable.FactorsSnapshot=snap;}
  public static void Remove(Circuit circuit){if(circuit==null)throw new ArgumentNullException("circuit");circuit.Cable.FactorsSnapshot=null;}
  public static string Describe(Circuit circuit){var cable=circuit.Cable;string condition;Applicable(circuit,out condition);var text=new StringBuilder();text.Append("Ft="+cable.TemperatureFactor.ToString("G8",CultureInfo.CurrentCulture)+"; Fg="+cable.GroupingFactor.ToString("G8",CultureInfo.CurrentCulture)+". "+condition);var s=cable.FactorsSnapshot;if(s!=null){text.Append(" Ambiente "+s.Conditions.AmbientC+" °C; circuitos agrupados "+s.Conditions.GroupCount+"; arranjo "+s.Conditions.Arrangement+"; condutores carregados "+s.Conditions.LoadedConductors+". Base de ampacidade: "+s.Temperature.AmpacityReference+". Temperatura: "+s.Temperature.Id+", "+s.Temperature.Source+", versão "+s.Temperature.DataVersion+". Agrupamento: "+s.Grouping.Id+", "+s.Grouping.Source+", versão "+s.Grouping.DataVersion+". Sem interpolação ou tabela normativa presumida.");}return text.ToString();}
  static double Number(string text){double value;if(text.Contains('.')&&text.Contains(','))throw new InvalidDataException("Número ambíguo.");if(!Double.TryParse(text.Trim().Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||Double.IsNaN(value)||Double.IsInfinity(value))throw new InvalidDataException("Número inválido.");return value;}
  static int Integer(string text){int value;if(!Int32.TryParse(text,NumberStyles.Integer,CultureInfo.InvariantCulture,out value))throw new InvalidDataException("Inteiro inválido.");return value;}
  static T EnumValue<T>(string text){T result;try{result=(T)Enum.Parse(typeof(T),text,true);}catch{throw new InvalidDataException("Tipo de fator/material/isolação inválido.");}if(!Enum.IsDefined(typeof(T),result))throw new InvalidDataException("Valor de enumeração inválido.");return result;}
  public static List<CableFactorRow> Import(string file){if(new FileInfo(file).Length>32*1024*1024)throw new InvalidDataException("Tabela de fatores excede 32 MiB.");var rows=CatalogData.Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF'));if(rows.Count==0||String.Join(";",rows[0])!=Header||rows.Count>100001)throw new InvalidDataException("Cabeçalho ou tamanho da tabela de fatores inválido.");var result=new List<CableFactorRow>();var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);for(int i=1;i<rows.Count;i++){try{var row=rows[i];if(row.Length!=15)throw new InvalidDataException("Esperadas 15 colunas.");var value=new CableFactorRow{Id=row[0],Kind=EnumValue<CableFactorKind>(row[1]),Material=EnumValue<ConductorMaterial>(row[2]),Insulation=EnumValue<CableInsulation>(row[3]),Installation=row[4],Arrangement=row[5],AmbientC=Number(row[6]),GroupCount=Integer(row[7]),LoadedConductors=Integer(row[8]),MinSectionMm2=Number(row[9]),MaxSectionMm2=Number(row[10]),Factor=Number(row[11]),AmpacityReference=row[12],Source=row[13],DataVersion=row[14]};value.Validate();if(!ids.Add(value.Id.Trim()))throw new InvalidDataException("ID de fator duplicado.");result.Add(value);}catch(Exception ex){throw new InvalidDataException("Fator na linha "+(i+1)+": "+ex.Message,ex);}}return result;}
  static string Quote(string text){return "\""+text.Replace("\"","\"\"")+"\"";}
  public static void Export(IEnumerable<CableFactorRow> rows,string file){var items=rows.ToList();if(items.Count>100000)throw new InvalidDataException("Tabela de fatores excede 100000 itens.");var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var row in items){if(row==null)throw new InvalidDataException("Linha de fator ausente.");row.Validate();if(!ids.Add(row.Id.Trim()))throw new InvalidDataException("ID de fator duplicado.");}string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{long bytes=3+Encoding.UTF8.GetByteCount(Header+"\r\n");using(var writer=new StreamWriter(temp,false,new UTF8Encoding(true))){writer.WriteLine(Header);foreach(var row in items){var fields=new[]{row.Id,row.Kind.ToString(),row.Material.ToString(),row.Insulation.ToString(),row.Installation,row.Arrangement??"",row.AmbientC.ToString("R",CultureInfo.InvariantCulture),row.GroupCount.ToString(CultureInfo.InvariantCulture),row.LoadedConductors.ToString(CultureInfo.InvariantCulture),row.MinSectionMm2.ToString("R",CultureInfo.InvariantCulture),row.MaxSectionMm2.ToString("R",CultureInfo.InvariantCulture),row.Factor.ToString("R",CultureInfo.InvariantCulture),row.AmpacityReference,row.Source,row.DataVersion};string line=String.Join(";",fields.Select(Quote));bytes+=Encoding.UTF8.GetByteCount(line+"\r\n");if(bytes>32L*1024*1024)throw new InvalidDataException("Tabela de fatores excede 32 MiB; destino preservado.");writer.WriteLine(line);}}if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
 }
}
